</head>

<body class="bg-gray-100">

    <!-- Main Chat -->
    <div class="chat-wrapper max-w-md mx-auto bg-white flex flex-col">

        <!-- Top Bar -->
        <div class="bg-blue-600 text-white p-4 flex items-center gap-4 shadow shrink-0">

            <a href="viewchat.php">
                <button class="text-2xl">
                    ←
