            <img src="profilepics/<?= $result['profile_image'] ?>" class="w-12 h-12 rounded-full object-cover">

            <div class="flex-1">
                <h1 class="font-semibold text-lg">
                    <?= $chat ?>
                </h1>

                <p class="text-sm text-blue-100">
                    <?php
                        $rtime = new DateTime($result['last_seen']);
