    </div>

    <script>
        
    var privateKey = null;
    const placeholderImage =
        "data:image/png;base64,";
    const fileUpload = document.getElementById("fileUpload");
    const previewArea = document.getElementById("previewArea");
    const chatArea = document.getElementById("chatArea");
    const msgInput = document.getElementById("msgInput");
    const senderbtn = document.getElementById("senderbtn");
    let chat = document.getElementById("chatArea");
    let peerPublicKey = <?= json_encode($public_key) ?>;
    //sent message
    async function sentmsg() {
        if (msgInput.value.trim() == '' && fileUpload.files.length === 0) {
            return;
        }
        try {
            if (fileUpload.files.length > 0) {

                const formData = new FormData();
                
                if (fileUpload.files.length > 0) {
                    const file = fileUpload.files[0];
                    const buffer = await file.arrayBuffer();
                    const bytes = new Uint8Array(buffer);
                    const fileBase64 = sodium.to_base64(bytes);
                    let encrypted_file_data = encrypt(peerPublicKey, privateKey, fileBase64);
                    const encryptedFile = new File(
                        [encrypted_file_data],
                        file.name ,
                        { type: "application/octet-stream" }
                    );
                    formData.append('file', encryptedFile);
                }

                if (fileUpload.files[0].type.startsWith("image/")) {
                    formData.append('message_type', "image");
                } else if (fileUpload.files[0].type.includes("pdf")) {
                    formData.append('message_type', "file");
                } else if (fileUpload.files[0].type.startsWith("video")) {
                    formData.append('message_type', "video");
                }

                
                const toSend = encrypt(peerPublicKey, privateKey, msgInput.value);

                formData.append('message', toSend);
                formData.append('receiver_id', <?=$chatid;?>);
                formData.append('file_size', (fileUpload.files[0].size / 1024 / 1024).toFixed(2))

                const res = await fetch('sent_msg.php', {
                    method: 'POST',
                    body: formData
                });
                msgInput.value = '';
                fileUpload.value = "";
                previewArea.innerHTML = "";
            } else {
                const formData = new FormData();

                const toSend = encrypt(peerPublicKey, privateKey, msgInput.value);
                formData.append('message', toSend);
                formData.append('receiver_id', <?=$chatid;?>);
                const res = await fetch('sent_msg.php', {
                    method: 'POST',
                    body: formData
                });

                msgInput.value = '';
            }
        } catch (error) {
            console.error("Error sending data : ", error);
        }

    }
    senderbtn.addEventListener("click", sentmsg);
    //sent message END

    // File Preview
    fileUpload.addEventListener("change", () => {

        previewArea.innerHTML = "";

        Array.from(fileUpload.files).forEach(file => {

            const item = document.createElement("div");

            item.className =
                "bg-gray-100 rounded-lg p-3 flex items-center gap-3";
            let icon = "📄";
            if (file.type.startsWith("image/")) {
                icon = "🌄";
            }

            item.innerHTML = `
                    <div class="text-2xl">${icon}</div>

                    <div class="flex-1 overflow-hidden">
                        <h2 class="font-medium truncate">
                            ${file.name}
                        </h2>

                        <p class="text-sm text-gray-500">
                            ${(file.size / 1024 / 1024).toFixed(2)} MB
                        </p>
                            <button class="text-2xl closefile">
                                ✖
                            </button>
                    </div>
                `;
            previewArea.appendChild(item);
        });

    });

    previewArea.addEventListener("click", (e) => {
        if (e.target.closest(".closefile")) {
            fileUpload.value = "";
            previewArea.innerHTML = "";

        }
    });

    function scrollToBottom() {
        chatArea.scrollTop = chatArea.scrollHeight;
    }

    scrollToBottom();

    if (window.visualViewport) {

        window.visualViewport.addEventListener("resize", () => {

            document.querySelector(".chat-wrapper").style.height =
                window.visualViewport.height + "px";

            scrollToBottom();
        });
    }

    let lastMessageId = 0;
    let beforeMessageId = 0;
    let is_first_load = true;
    let is_load_old = false;
    let oldHeight = 0;
    let we_sent = false;
    let user = <?= $_SESSION['id']; ?>;
    //root 7
    async function loadMessages() {
        try {
            let response;
            if (is_first_load) {
                response = await fetch("load_msg.php?user=<?= $user?>&chat=<?= $chatid?>");
            } else {
                if (is_load_old) {
                    oldHeight = chatArea.scrollHeight;
                    response = await fetch("load_msg.php?user=<?= $user?>&chat=<?= $chatid?>&before_message_id=" +
                        beforeMessageId);
                    is_load_old = false;
                } else {
                    response = await fetch("load_msg.php?user=<?= $user?>&chat=<?= $chatid?>&last_message_id=" +
                        lastMessageId);
                }
            }

            const data = await response.json();

            if (data.length === 0) {
                return;
            }

            data.forEach(item => {
                if (item.msg.trim() !== "" || item.type !== "text") {
                    let recevied = `${item.sender}`;
                    let messageHtml = "";
                    const time12hr = timeto12(item.time);

                    if (is_first_load) {
                        beforeMessageId = data[0].msg_id;
                        // is_first_load = false;
                    }
                    if (item.type == "image") {
                        //image
                        if (recevied != user) {
                            //we got it
                            let plaintext = decrypt(peerPublicKey , privateKey, item.msg);
                            messageHtml = `<div class="flex msg-d" data-date="${item.msg_date}">
                                        <div class="bg-white-500 p-2 rounded-2xl max-w-[75%] shadow">
                                            <img src="${placeholderImage}" data-src="uploads/${item.filename_store}" class="rounded-xl w-full object-cover clicktoload">
                                            <p>${escapeHtml(plaintext)}</p>
                                            <span class="text-xs text-gray-500 block text-right mt-1">
                                            ${time12hr}
                                            </span></div> </div>`;
                        } else {
                            //we sent it
                            let plaintext = decrypt(peerPublicKey , privateKey, item.msg);
                            messageHtml = `<div class="flex justify-end msg-d" data-date="${item.msg_date}">
                                        <div class="bg-blue-500 text-blue-100 p-2 rounded-2xl max-w-[75%] shadow">
                                            <img src="${placeholderImage}" data-src="uploads/${item.filename_store}" class="rounded-xl w-full object-cover clicktoload">
                                            <p>${escapeHtml(plaintext)}</p>
                                            <span class="text-xs text-blue-100 block text-right mt-1">
                                            ${time12hr}
                                            </span></div> </div>`;

                        }
                    } else if (item.type == "video") {
                        if (recevied != user) {
                            //we got it
                            let plaintext = decrypt(peerPublicKey , privateKey, item.msg);
                            messageHtml = `<div class="flex msg-d" data-date="${item.msg_date}">
                                        <div class="bg-white-500 p-2 rounded-2xl max-w-[75%] shadow">
                                            <img data-video="uploads/${item.filename_store}" src="${placeholderImage}" class="rounded-xl w-full object-cover clicktovideo">
                                            <div class="spinner" hidden>
                                                
                                            </div>
                                            <p>${escapeHtml(plaintext)}</p>
                                            <span class="text-xs text-gray-500 block text-right mt-1">
                                            ${time12hr}
                                            </span></div> </div>`;
                        } else {
                            //we sent it
                            let plaintext = decrypt(peerPublicKey , privateKey, item.msg);
                            messageHtml = `<div class="flex justify-end msg-d" data-date="${item.msg_date}">
                                        <div class="bg-blue-500 p-2 rounded-2xl max-w-[75%] shadow">
                                            <img data-video="uploads/${item.filename_store}" src="${placeholderImage}" class="rounded-xl w-full object-cover clicktovideo">
                                            <div class="spinner" hidden>
                                                
                                            </div>
                                            <p>${escapeHtml(plaintext)}</p>
                                            <span class="text-xs text-blue-100 block text-right mt-1">
                                            ${time12hr}
                                            </span></div> </div>`;
                        }
                    } else if (item.type == "file") {
                        if (recevied != user) {
                            let plaintext = decrypt(peerPublicKey , privateKey, item.msg);
                            messageHtml = `<div class="flex msg-d" data-date="${item.msg_date}">
                                            <div class="bg-white px-4 py-3 rounded-2xl shadow max-w-[75%] flex items-center gap-3">
                                            <div class="text-3xl">
                                                <a href="uploads/${item.filename_store}" download="${escapeHtml(item.filename)}">📄</a>
                                            </div>
                                            <div>
                                                <h2 class="font-medium">
                                                    ${escapeHtml(item.filename)}
                                                </h2>
                                                <p>${escapeHtml(plaintext)}</p>
                                                <p class="text-sm text-gray-500">
                                                    ${item.filesize} MB
                                                </p><span class="text-xs text-blue-100 block text-right mt-1">
                                            ${time12hr}
                                        </span></div></div></div>`;
                        } else {
                            let plaintext = decrypt(peerPublicKey , privateKey, item.msg);
                            messageHtml = `<div class="flex justify-end msg-d" data-date="${item.msg_date}">
                                            <div class="bg-blue-500 px-4 py-3 rounded-2xl shadow max-w-[75%] flex items-center gap-3">
                                            <div class="text-3xl">
                                                <a href="#" class="download-encrypted-file" data-file="uploads/${item.filename_store}" data-name="${escapeHtml(item.filename)}"> 📄 </a>
                                            </div>
                                            <div>
                                                <h2 class="font-medium">
                                                   ${escapeHtml(item.filename)}
                                                </h2>
                                                 <p>${escapeHtml(plaintext)}</p>
                                                <p class="text-sm text-blue-100">
                                                    ${item.filesize} MB
                                                </p>
                                                 <span class="text-xs text-blue-100 block text-right mt-1">
                                            ${time12hr}
                                        </span></div></div></div>`;
                        }
                    } else {
                        if (recevied != user) {
                            //we got it
                            let plaintext = decrypt(peerPublicKey , privateKey, item.msg);
                            messageHtml = `<div class="flex msg-d" data-date="${item.msg_date}">
                                                <div class="bg-white px-4 py-3 rounded-2xl shadow max-w-[75%]">
                                                    <p>${escapeHtml(plaintext)}</p>
                                                    <span class="text-xs text-gray-500 block text-right mt-1">${time12hr}</span>
                                            </div></div>`;
                        } else {
                            //we sent it
                            let plaintext = decrypt(peerPublicKey , privateKey, item.msg);
                            messageHtml = `<div class="flex justify-end msg-d" data-date="${item.msg_date}">
                                        <div class="bg-blue-500 text-white px-4 py-3 rounded-2xl shadow max-w-[75%]">
                                            <p>${escapeHtml(plaintext)}</p>
                                        <span class="text-xs text-blue-100 block text-right mt-1">
                                            ${time12hr}
                                        </span>
                                    </div>
                                    </div>`;
                        }
                    }

                    if (item.is_old) {
                        chat.insertAdjacentHTML("afterbegin", messageHtml);
                        beforeMessageId = data[data.length - 1].msg_id;
                    } else {
                        chat.insertAdjacentHTML("beforeend", messageHtml);
                        lastMessageId = item.msg_id;
                    }
                }

            });
            if (data.length > 0) {
                renderDateLabels();
                if (data[0].is_old) {
                    const newHeight = chatArea.scrollHeight;
                    chatArea.scrollTop = newHeight - oldHeight;
                } else if (we_sent) {
                    scrollToBottom();
                    we_sent = false;
                }
            }
            if(is_first_load){
                scrollToBottom();
                is_first_load=false;
            }
        } catch (error) {
            console.error("Error fetching data:", error);
        } finally {
            setTimeout(loadMessages, 1000);
        }
    }


    // load img
    document.addEventListener("click", async (e) => {
        if (!e.target.classList.contains("clicktoload")) return;
        const img = e.target;
        try {
            const response = await fetch(img.dataset.src);
            const encryptedData = await response.text();
            const fileBase64 = decrypt(peerPublicKey, privateKey, encryptedData);
            const bytes = sodium.from_base64(fileBase64);
            const blob = new Blob([bytes]);
            const url = URL.createObjectURL(blob);
            img.src = url;
            img.removeAttribute("data-src");
            img.style.cursor = "default";
            img.classList.remove("clicktoload");
        } catch (err) {
            console.error(err);
        }
    });
    //load video
    document.addEventListener("click", async (e) => {
        if (!e.target.classList.contains("clicktovideo")) return;

        const img = e.target;
        const wrapper = img.parentElement;
        const spinner = wrapper.querySelector(".spinner");

        spinner.hidden = false;

        try {
            const response = await fetch(img.dataset.video);
            const encryptedData = await response.text();
            const fileBase64 = decrypt(peerPublicKey, privateKey, encryptedData);
            const bytes = sodium.from_base64(fileBase64);
            const blob = new Blob([bytes], {
                type: "video/mp4"
            });
            const url = URL.createObjectURL(blob);
            const video = document.createElement("video");
            video.src = url;
            video.controls = true;
            video.autoplay = true;
            video.addEventListener("canplay", () => {
                spinner.hidden = true;
            });
            video.addEventListener("waiting", () => {
                spinner.hidden = false;
            });
            video.addEventListener("playing", () => {
                spinner.hidden = true;
            });
            img.replaceWith(video);
        } catch (err) {
            spinner.hidden = true;
            console.error(err);
        }
    });
    //load file
    document.addEventListener("click", async (e) => {
        const link = e.target.closest(".download-encrypted-file");
        if (!link) return;

        e.preventDefault();

        try {
            const response = await fetch(link.dataset.file);
            const encryptedData = await response.text();
            const fileBase64 = decrypt(peerPublicKey, privateKey, encryptedData);
            const bytes = sodium.from_base64(fileBase64);
            const blob = new Blob([bytes]);
            const url = URL.createObjectURL(blob);
            const a = document.createElement("a");
            a.href = url;
            a.download = link.dataset.name;
            a.click();
            setTimeout(() => URL.revokeObjectURL(url), 5000);
        } catch (err) {
            console.error(err);
        }
    });


    setInterval(() => {
        fetch("lastseen.php");
    }, 45000);


    let loading = false;
    chatArea.addEventListener("scroll", async () => {
        if (loading) return;
        if (chatArea.scrollTop <= 0) {
            loading = true;
            is_load_old = true;
            loading = false;
        }
    });

    window.addEventListener("keydown", (event) => {
        if (event.key === "Enter") {
            sentmsg();
            we_sent = true;
        }
    });

    async function getKey() {
            const getData = new FormData();
            getData.append('name', <?= json_encode($_SESSION['user']) ?>);

            const res = await fetch('get_private_key.php', {
                method: 'POST',
                body: getData
            });

            const data = await res.json();

            var salt = sodium.from_base64(data.salt);
            const encryptedKey = sodium.from_base64(data.private_key);
            var nonce = sodium.from_base64(data.nonce);

            var encryptionKey = sodium.crypto_pwhash(
                32,
                <?= json_encode($_SESSION['ps'] ?? '') ?>,
                salt,
                sodium.crypto_pwhash_OPSLIMIT_INTERACTIVE,
                sodium.crypto_pwhash_MEMLIMIT_INTERACTIVE,
                sodium.crypto_pwhash_ALG_DEFAULT
            );

            var decryptedPrivateKey = sodium.crypto_secretbox_open_easy(
                encryptedKey,
                nonce,
                encryptionKey
            );
            privateKey = decryptedPrivateKey;
            return decryptedPrivateKey;
        }
        (async () => {
            await window.sodium.ready;
            privateKey = await getKey();
            if (privateKey) {
                loadMessages();
            }
        })();
    </script>

</body>

